const trimRuleRuns = `-- name: TrimRuleRuns :execrows
DELETE FROM board_rule_runs WHERE id IN (
    SELECT x.id FROM (
        SELECT id, created_at, row_number() OVER (PARTITION BY rule_id ORDER BY created_at DESC, id DESC) AS n
        FROM board_rule_runs
    ) x WHERE x.n > 100 OR x.created_at < now() - interval '90 days'
    LIMIT 5000
)
`

// The sweeper: runs older than 90 days and all but the newest 100 of each rule.
func (q *Queries) TrimRuleRuns(ctx context.Context) (int64, error) {
	result, err := q.db.Exec(ctx, trimRuleRuns)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const trimTaskGitLinks = `-- name: TrimTaskGitLinks :execrows
DELETE FROM task_git_links d WHERE d.id IN (
    SELECT o.id FROM task_git_links o WHERE o.task_id = $1::uuid
    ORDER BY (o.kind = 'commit') DESC, o.updated_at, o.id
    LIMIT greatest((SELECT count(*) FROM task_git_links c WHERE c.task_id = $1::uuid) - 50, 0)
)
`

// ≤ 50 links per task: the oldest commits go first, then the oldest others.
func (q *Queries) TrimTaskGitLinks(ctx context.Context, taskID uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, trimTaskGitLinks, taskID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateBoardGitBacklink = `-- name: UpdateBoardGitBacklink :one
UPDATE board_git SET backlink = coalesce($1, backlink),
    api_token_enc = CASE WHEN $2::boolean THEN $3
        WHEN $4::text IS NOT NULL AND $4::text <> gitlab_url THEN NULL
        ELSE api_token_enc END,
    gitlab_url = coalesce($4, gitlab_url),
    backlink_error = CASE WHEN $2::boolean OR $4 IS NOT NULL THEN '' ELSE backlink_error END
WHERE board_id = $5
RETURNING board_id, provider, secret_enc, created_by, created_at, last_event_at, last_error, events_count, backlink, api_token_enc, gitlab_url, backlink_error
`

type UpdateBoardGitBacklinkParams struct {
	Backlink    *bool
	SetToken    bool
	ApiTokenEnc []byte
	GitlabUrl   *string
	BoardID     uuid.UUID
}

// PATCH /api/boards/{id}/git: unset arguments keep the stored value; a new token or address
// clears the last backlink error. The token is bound to its address: a changed address without
// a new token forgets the stored one (it never follows the board to another host).
func (q *Queries) UpdateBoardGitBacklink(ctx context.Context, arg UpdateBoardGitBacklinkParams) (BoardGit, error) {
	row := q.db.QueryRow(ctx, updateBoardGitBacklink,
		arg.Backlink,
		arg.SetToken,
		arg.ApiTokenEnc,
		arg.GitlabUrl,
		arg.BoardID,
	)
	var i BoardGit
	err := row.Scan(
		&i.BoardID,
		&i.Provider,
		&i.SecretEnc,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.LastEventAt,
		&i.LastError,
		&i.EventsCount,
		&i.Backlink,
		&i.ApiTokenEnc,
		&i.GitlabUrl,
		&i.BacklinkError,
	)
	return i, err
}

